            new_power = (current_power * 2) % MOD
            if new_power > current_power:
                result.append('x')
                current_power = new_power
            else:
                result.append('o')

    return ''.join(result)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    M = int(data[0])
    S = int(data[1])
    steps = data[2]

    print(max_discharge_power(M, S, steps))

